<?php
declare(strict_types=1); namespace App\Services\Hrd;
use App\Models\{PayrollDisbursement,PayrollPaymentBatch,PersonnelBankAccount,PersonnelPayroll,User}; use Illuminate\Auth\Access\AuthorizationException; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class PayrollPaymentBatchService { public function create(array $payrollIds,User $maker):PayrollPaymentBatch{return DB::transaction(function()use($payrollIds,$maker){$payrolls=PersonnelPayroll::whereKey($payrollIds)->whereIn('status',['processed','approved'])->get();if($payrolls->count()!==count(array_unique($payrollIds)))throw ValidationException::withMessages(['payroll'=>'Payroll belum valid.']);$batch=PayrollPaymentBatch::create(['batch_number'=>'PAY-'.now()->format('YmdHis').'-'.Str::upper(Str::random(4)),'payroll_period'=>$payrolls->min('period_start').' / '.$payrolls->max('period_end'),'total_records'=>$payrolls->count(),'total_amount'=>$payrolls->sum('total'),'status'=>'awaiting_approval','created_by'=>$maker->id,'external_id'=>(string)Str::uuid()]);foreach($payrolls as $p){$a=PersonnelBankAccount::where('personnel_id',$p->personnel_id)->where('is_primary',true)->firstOrFail();PayrollDisbursement::create(['payroll_payment_batch_id'=>$batch->id,'personnel_payroll_id'=>$p->id,'personnel_id'=>$p->personnel_id,'bank_account_snapshot'=>['bank_code'=>$a->bank_code,'account_number'=>$a->account_number,'holder'=>$a->account_holder_name],'amount'=>$p->total,'provider'=>'BRI','external_id'=>(string)Str::uuid(),'status'=>'pending']);}activity('payroll')->causedBy($maker)->performedOn($batch)->log('Membuat batch pembayaran payroll.');return $batch;});} public function approve(PayrollPaymentBatch $batch,User $checker):void{if($batch->created_by===$checker->id)throw new AuthorizationException('Pembuat batch tidak boleh menjadi approver.');if($batch->status!=='awaiting_approval')throw ValidationException::withMessages(['status'=>'Batch tidak menunggu persetujuan.']);$batch->update(['status'=>'approved','approved_by'=>$checker->id,'approved_at'=>now()]);activity('payroll')->causedBy($checker)->performedOn($batch)->log('Menyetujui batch pembayaran payroll.');} }
